<?php require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/config/db.php';if(empty($_SESSION['user_id'])){header('Location: auth/login.php');exit;}$rows=[];try{$p=db();if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf_token']??null)){$q=$p->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$q->execute([$_SESSION['user_id']]);}$q=$p->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$_SESSION['user_id']]);$rows=$q->fetchAll();}catch(Throwable $e){}$pageTitle='Notifications';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?><main class="container py-5"><div class="d-flex justify-content-between"><h1 class="h2">Notifications</h1><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-outline-brand">Mark all as read</button></form></div><?php foreach($rows as $n):?><div class="profile-section my-2 <?=$n['is_read']?'':'border-success'?>"><span class="badge text-bg-light"><?=e(str_replace('_',' ',$n['type']))?></span> <?=e($n['message'])?><small class="d-block text-secondary mt-1"><?=e($n['created_at'])?></small></div><?php endforeach;if(!$rows):?><p class="text-secondary">No notifications.</p><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?>
